RETURNS TEXT AS $$
  SELECT ((SELECT NULLIF(intelligences_id, '') FROM intelligences WHERE intelligences_id = p_intelligences_id))::text;
$$ LANGUAGE sql STABLE;

-- calc_intelligences_assessment_count
-- Field: Intelligences.AssessmentCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_intelligences_assessment_count(p_intelligences_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM assessments WHERE intelligence = (SELECT NULLIF(intelligences_id, '') FROM intelligences WHERE intelligences_id = p_intelligences_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_intelligences_total_weighted_score
-- Field: Intelligences.TotalWeightedScore
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_intelligences_total_weighted_score(p_intelligences_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COALESCE(SUM((((SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (erb_r1.raw_score) AS v OFFSET 0) __safe_numeric), 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_assessments_capability_weight(erb_r1.assessments_id)) AS v OFFSET 0) __safe_numeric), 0)))::numeric))::numeric)::numeric), 0) FROM assessments erb_r1 WHERE intelligence = p_intelligences_id))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_intelligences_taxonomy_class
-- Field: Intelligences.TaxonomyClass
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_intelligences_taxonomy_class(p_intelligences_id TEXT)
RETURNS TEXT AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_intelligences_total_weighted_score(p_intelligences_id) AS val) SELECT (CASE WHEN COALESCE(((SELECT val FROM __erb_dedup_v1))::NUMERIC, 0) >= 350 THEN ('Generalist')::text ELSE (CASE WHEN COALESCE(((SELECT val FROM __erb_dedup_v1))::NUMERIC, 0) >= 220 THEN ('Broad')::text ELSE ('Narrow')::text END)::text END)::text;
$$ LANGUAGE sql STABLE;

